"""Evaluation helpers (R9, R10).

Every function takes scores FIRST and labels SECOND so labels can only be
consumed after predictions exist - the unsupervised protocol of Section 5.1.
"""

from __future__ import annotations

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)


def auc_roc(scores, labels):
    return float(roc_auc_score(np.asarray(labels), np.asarray(scores)))


def auc_pr(scores, labels):
    """Primary AUC-PR: average precision (ADBench convention)."""
    return float(average_precision_score(np.asarray(labels), np.asarray(scores)))


def auc_pr_trapz(scores, labels):
    """Secondary AUC-PR: trapezoidal area under the sklearn PR curve."""
    precision, recall, _ = precision_recall_curve(np.asarray(labels), np.asarray(scores))
    return float(-np.sum(np.diff(recall) * (precision[:-1] + precision[1:]) / 2.0))


def summarize(values):
    v = np.asarray(values, dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if len(v) > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(len(v)),
        "values": [float(x) for x in v],
    }

